/**
 * Test the Integer Primitive
 */
@Test
public void testIntegerPrimitive() throws IntegerDecoderException {
    BerValue value = new BerValue();
    value.init(1);
    value.setData(new byte[] // res = 0
    { 0x00 });
    assertEquals(0, IntegerDecoder.parse(value));
    value.reset();
    value.init(1);
    value.setData(new byte[] // res = 1
    { 0x01 });
    assertEquals(1, IntegerDecoder.parse(value));
    value.reset();
    value.init(1);
    value.setData(new byte[] // res = 255
    { (byte) 0xFF });
    assertEquals(-1, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = 255
    { (byte) 0x00, (byte) 0xFF });
    assertEquals(255, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = 1
    { 0x00, 0x01 });
    assertEquals(1, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = 256
    { 0x01, 0x00 });
    assertEquals(256, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = 257
    { 0x01, 0x01 });
    assertEquals(257, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = 511
    { 0x01, (byte) 0xFF });
    assertEquals(511, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = 512
    { 0x02, 0x00 });
    assertEquals(512, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = 32767
    { 0x7F, (byte) 0xFF });
    assertEquals(32767, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = -32768
    { (byte) 0x80, 0x00 });
    assertEquals(-32768, IntegerDecoder.parse(value));
    value.reset();
    value.init(2);
    value.setData(new byte[] // res = -65535
    { (byte) 0xFF, (byte) 0xFF });
    assertEquals(-1, IntegerDecoder.parse(value));
    value.reset();
    value.init(3);
    value.setData(new byte[] // res = 65535
    { 0x00, (byte) 0xFF, (byte) 0xFF });
    assertEquals(65535, IntegerDecoder.parse(value));
    value.reset();
    value.init(3);
    // res = 65536
    value.setData(new byte[] { 0x01, 0x00, 0x00 });
    assertEquals(65536, IntegerDecoder.parse(value));
    value.reset();
    value.init(3);
    // res = 8388607
    value.setData(new byte[] { 0x7F, (byte) 0xFF, (byte) 0xFF });
    assertEquals(8388607, IntegerDecoder.parse(value));
    value.reset();
    value.init(3);
    // res = -8388608
    value.setData(new byte[] { (byte) 0x80, (byte) 0x00, (byte) 0x00 });
    assertEquals(-8388608, IntegerDecoder.parse(value));
    value.reset();
    value.init(3);
    // res = -1
    value.setData(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF });
    assertEquals(-1, IntegerDecoder.parse(value));
    value.reset();
    value.init(4);
    // res = 16777215
    value.setData(new byte[] { 0x00, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF });
    assertEquals(16777215, IntegerDecoder.parse(value));
    value.reset();
    value.init(4);
    // res = 2^31 - 1 = MaxInt
    value.setData(new byte[] { (byte) 0x7F, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF });
    assertEquals(Integer.MAX_VALUE, IntegerDecoder.parse(value));
    value.reset();
    value.init(4);
    // res = 2^31 = MinInt
    value.setData(new byte[] { (byte) 0x80, (byte) 0x00, (byte) 0x00, (byte) 0x00 });
    assertEquals(Integer.MIN_VALUE, IntegerDecoder.parse(value));
    value.reset();
    value.init(4);
    // res = -1
    value.setData(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF });
    assertEquals(-1, IntegerDecoder.parse(value));
    value.reset();
    value.init(5);
    // res = 2^31 = MinInt
    value.setData(new byte[] { 0x00, (byte) 0x80, (byte) 0x00, (byte) 0x00, (byte) 0x00 });
    assertEquals(Integer.MIN_VALUE, IntegerDecoder.parse(value));
    value.reset();
    value.init(5);
    // res = 2^31 = MinInt
    value.setData(new byte[] { 0x00, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, (byte) 0xFF });
    assertEquals(-1, IntegerDecoder.parse(value));
    value.reset();
    try {
        value.init(5);
        // res = 2^31 = MinInt
        value.setData(new byte[] // res
        { 0x00, (byte) 0x7F, (byte) 0x00, (byte) 0x00, (byte) 0x00 });
        IntegerDecoder.parse(value);
        fail();
    } catch (IntegerDecoderException ide) {
        // Expected
    }
}

