    assertTrue(attr.contains("top"));
    assertTrue(attr.contains("apApplication"));
    attr = entry.get("displayname");
    assertTrue(attr.contains("app1"));
    attr = entry.get("userPassword");
    assertEquals("", attr.get().getString());
}

