    0x01, // CHOICE { ..., abandonRequest
    0x02, // controls [0] Controls OPTIONAL }
    (byte) 0xA0, // controls [0] Controls OPTIONAL }
    (byte) 0x81, // controls [0] Controls OPTIONAL }
    (byte) 0x90, // Control ::= SEQUENCE {
    0x30, // Control ::= SEQUENCE {
    0x2E, // controlType LDAPOID,
    0x04, // controlType LDAPOID,
    0x16, // SortRequest
    '1', '.', '2', '.', '8', '4', '0', '.', '1', '1', '3', '5', '5', '6', '.', '1', '.', '4', '.', '4', '7', '3', // criticality BOOLEAN DEFAULT FALSE,
    0x01, // criticality BOOLEAN DEFAULT FALSE,
    0x01, // criticality BOOLEAN DEFAULT FALSE,
    (byte) 0xFF, // controlValue OCTET STRING OPTIONAL }
    0x04, // controlValue OCTET STRING OPTIONAL }
    0x11, // SortKeyList ::= SEQUENCE OF SEQUENCE {
    0x30, // SortKeyList ::= SEQUENCE OF SEQUENCE {
    0x0F, // SEQUENCE
    0x30, // SEQUENCE
    0x07, // attributeType   AttributeDescription,
    0x04, // attributeType   AttributeDescription,
    0x02, 'c', 'n', // reverseOrder    [1] BOOLEAN DEFAULT FALSE }
    (byte) 0x81, // reverseOrder    [1] BOOLEAN DEFAULT FALSE }
    0x01, // reverseOrder    [1] BOOLEAN DEFAULT FALSE }
    (byte) 0xFF, // SEQUENCE
    0x30, // SEQUENCE
    0x04, // attributeType   AttributeDescription,
    0x04, // attributeType   AttributeDescription,
    0x02, 's', 'n', // Control ::= SEQUENCE {
    0x30, // Control ::= SEQUENCE {
    0x25, // controlType LDAPOID,
    0x04, // controlType LDAPOID,
    0x16, // PagedResults
    '1', '.', '2', '.', '8', '4', '0', '.', '1', '1', '3', '5', '5', '6', '.', '1', '.', '4', '.', '3', '1', '9', // controlValue OCTET STRING OPTIONAL }
    0x04, // controlValue OCTET STRING OPTIONAL }
    0x0B, // realSearchControlValue ::= SEQUENCE {
    0x30, // realSearchControlValue ::= SEQUENCE {
    0x09, // size            INTEGER (0..maxInt),
    0x02, // size            INTEGER (0..maxInt),
    0x01, // size            INTEGER (0..maxInt),
    0x10, // cookie          OCTET STRING
    0x04, // cookie          OCTET STRING
    0x04, 't', 't', 't', 't', // Control ::= SEQUENCE {
    0x30, // Control ::= SEQUENCE {
    0x1C, // controlType LDAPOID,
    0x04, // controlType LDAPOID,
    0x17, // ManageDsaIT
    '2', '.', '1', '6', '.', '8', '4', '0', '.', '1', '.', '1', '1', '3', '7', '3', '0', '.', '3', '.', '4', '.', '2', // criticality BOOLEAN DEFAULT FALSE }
    0x01, // criticality BOOLEAN DEFAULT FALSE }
    0x01, // criticality BOOLEAN DEFAULT FALSE }
    (byte) 0xFF, // Control ::= SEQUENCE {
    0x30, // Control ::= SEQUENCE {
    0x19, // controlType LDAPOID}
    0x04, // controlType LDAPOID}
    0x17, // Cascade
    '1', '.', '3', '.', '6', '.', '1', '.', '4', '.', '1', '.', '1', '8', '0', '6', '0', '.', '0', '.', '0', '.', '1' });
    stream.flip();
    // Allocate a LdapMessageContainer Container
    LdapMessageContainer<AbandonRequest> ldapMessageContainer = new LdapMessageContainer<>(codec);
    // Decode the PDU
    Asn1Decoder.decode(stream, ldapMessageContainer);
    // Check that everything is OK
    AbandonRequest abandonRequest = ldapMessageContainer.getMessage();
    // Copy the message
    AbandonRequest internalAbandonRequest = new AbandonRequestImpl(abandonRequest.getAbandoned());
    internalAbandonRequest.setMessageId(abandonRequest.getMessageId());
    assertEquals(3, abandonRequest.getMessageId());
    assertEquals(2, abandonRequest.getAbandoned());
    // Check the Controls
    Map<String, Control> controls = abandonRequest.getControls();
    assertEquals(4, controls.size());
    Control control = controls.get("1.2.840.113556.1.4.473");
    assertEquals("1.2.840.113556.1.4.473", control.getOid());
    assertTrue(control instanceof SortRequest);
    assertTrue(control.isCritical());
    assertEquals(2, ((SortRequest) control).getSortKeys().size());
    internalAbandonRequest.addControl(control);
    control = controls.get("1.2.840.113556.1.4.319");
    assertEquals("1.2.840.113556.1.4.319", control.getOid());
    assertTrue(control instanceof PagedResults);
    assertFalse(control.isCritical());
    internalAbandonRequest.addControl(control);
    control = controls.get("2.16.840.1.113730.3.4.2");
    assertEquals("2.16.840.1.113730.3.4.2", control.getOid());
    assertTrue(control instanceof ManageDsaIT);
    assertTrue(control.isCritical());
    internalAbandonRequest.addControl(control);
    control = controls.get("1.3.6.1.4.1.18060.0.0.1");
    assertEquals("1.3.6.1.4.1.18060.0.0.1", control.getOid());
    assertTrue(control instanceof Cascade);
    assertFalse(control.isCritical());
    internalAbandonRequest.addControl(control);
    // Check the encoding
    Asn1Buffer buffer = new Asn1Buffer();
    ByteBuffer bb = LdapEncoder.encodeMessage(buffer, codec, internalAbandonRequest);
    // Check the length
    assertEquals(0x9C, bb.limit());
    // Don't check the PDU, as control are in a Map, and can be in a different order
    // So we decode the generated PDU, and we compare it with the initial message
    Asn1Decoder.decode(bb, ldapMessageContainer);
    AbandonRequest abandonRequest2 = ldapMessageContainer.getMessage();
    assertEquals(abandonRequest, abandonRequest2);
}

