    ByteBuffer stream = ByteBuffer.allocate(16);
    stream.put(new byte[] { // LDAPMessage ::=SEQUENCE {
    0x30, // LDAPMessage ::=SEQUENCE {
    0x33, // messageID MessageID
    0x02, // messageID MessageID
    0x01, // messageID MessageID
    0x01, // CHOICE { ..., bindRequest BindRequest, ...
    0x60, // CHOICE { ..., bindRequest BindRequest, ...
    0x2E, // BindRequest ::= APPLICATION[0] SEQUENCE {
    // version INTEGER (1..127),
    0x02, // version INTEGER (1..127),
    0x01, // version INTEGER (1..127),
    0x03, // name LDAPDN,
    0x04, // name LDAPDN,
    0x1F, 'u', 'i', 'd', '=' });
    stream.flip();
    // Allocate a LdapMessage Container
    LdapMessageContainer<Message> container = new LdapMessageContainer<>(codec);
    // Decode a BindRequest PDU
    Asn1Decoder.decode(stream, container);
    assertEquals(TLVStateEnum.VALUE_STATE_PENDING, container.getState());
    // Check the decoded PDU
    Message message = container.getMessage();
    assertEquals(1, message.getMessageId());
