/**
 * Test the decoding of a message with a wrong protocol operation
 */
@Test
public void testDecodeWrongProtocolOpMaxInt() {
    byte[] buffer = new byte[] { // LDAPMessage ::=SEQUENCE {
    0x30, // LDAPMessage ::=SEQUENCE {
    0x05, // messageID MessageID = 1
    0x02, // messageID MessageID = 1
    0x01, // messageID MessageID = 1
    0x01, // ProtocolOp
    0x42, // ProtocolOp
    0x00 };
    ByteBuffer stream = ByteBuffer.allocate(0x07);
    for (int i = 0; i < 256; i++) {
        buffer[5] = (byte) i;
        stream.put(buffer);
        stream.flip();
        // Allocate a LdapMessage Container
        Asn1Container ldapMessageContainer = new LdapMessageContainer<Message>(codec);
        // Decode a BindRequest PDU
        try {
            Asn1Decoder.decode(stream, ldapMessageContainer);
        } catch (DecoderException de) {
            switch(i) {
                case 0x42:
                case 0x4A:
                // AbandonRequest
                case 0x50:
                case 0x60:
                case 0x61:
                case 0x63:
                case 0x64:
                case 0x65:
                case 0x66:
                case 0x67:
                case 0x68:
                case 0x69:
                case 0x6B:
                case 0x6C:
                case 0x6D:
                case 0x6E:
                case 0x6F:
                case 0x73:
                case 0x77:
                case 0x78:
                    assertTrue(true);
                    break;
                default:
                    String res = de.getMessage();
                    if (res.startsWith("ERR_01200_BAD_TRANSITION_FROM_STATE") || res.startsWith("Universal tag ") || res.startsWith("ERR_01005_TRUNCATED_PDU Truncated PDU")) {
                        assertTrue(true);
                    } else {
                        fail("Bad exception : " + res);
                        return;
                    }
                    break;
            }
        }
        stream.clear();
    }
    assertTrue(true);
}

