public void testDecodeAddResponseEmptyResultCodeOKReferral() throws DecoderException, EncoderException {
    ByteBuffer stream = ByteBuffer.allocate(0x1A);
    stream.put(new byte[] { // LDAPMessage ::=SEQUENCE {
