    0x01, // messageID MessageID
    0x01, // CHOICE { ..., addResponse AddResponse, ...
    0x69, // CHOICE { ..., addResponse AddResponse, ...
    0x13, // resultCode success (Referral)
    0x0A, // resultCode success (Referral)
    0x01, // resultCode success (Referral)
    0x0A, // Empty matched Dn
    0x04, // Empty matched Dn
    0x00, // Empty errorMessage
    0x04, // Empty errorMessage
