@Test
public void testDecodeSearchResultEntrySuccessWithFollowingMessage() throws DecoderException, EncoderException, LdapException {
    ByteBuffer stream = ByteBuffer.allocate(0x66);
    stream.put(new byte[] { // LDAPMessage ::=SEQUENCE {
    0x30, // LDAPMessage ::=SEQUENCE {
    0x5F, // messageID MessageID
    0x02, // messageID MessageID
    0x01, // messageID MessageID
    0x02, // CHOICE { ..., searchResEntry SearchResultEntry,
    0x64, // CHOICE { ..., searchResEntry SearchResultEntry,
    0x5A, // ...
    // SearchResultEntry ::= [APPLICATION 4] SEQUENCE {
    // objectName LDAPDN,
    0x04, 0x13, 'u', 'i', 'd', '=', 'a', 'd', 'm', 'i', 'n', ',', 'o', 'u', '=', 's', 'y', 's', 't', 'e', 'm', // attributes PartialAttributeList }
    // PartialAttributeList ::= SEQUENCE OF SEQUENCE {
    0x30, // PartialAttributeList ::= SEQUENCE OF SEQUENCE {
    0x43, 0x30, 0x41, // type AttributeDescription,
    0x04, // type AttributeDescription,
    0x0B, 'o', 'b', 'j', 'e', 'c', 't', 'c', 'l', 'a', 's', 's', // vals SET OF AttributeValue }
    0x31, // vals SET OF AttributeValue }
    0x32, // AttributeValue ::= OCTET STRING
    0x04, // AttributeValue ::= OCTET STRING
    0x0D, 'i', 'n', 'e', 't', 'O', 'r', 'g', 'P', 'e', 'r', 's', 'o', 'n', // AttributeValue ::= OCTET STRING
    0x04, // AttributeValue ::= OCTET STRING
    0x14, 'o', 'r', 'g', 'a', 'n', 'i', 'z', 'a', 't', 'i', 'o', 'n', 'a', 'l', 'P', 'e', 'r', 's', 'o', 'n', // AttributeValue ::= OCTET STRING
    0x04, // AttributeValue ::= OCTET STRING
    0x06, 'p', 'e', 'r', 's', 'o', 'n', // AttributeValue ::= OCTET STRING
    0x04, // AttributeValue ::= OCTET STRING
    0x03, 't', 'o', 'p', // Start of the next message
    0x30, // Start of the next message
    0x45, // messageID MessageID ...
    0x02, // messageID MessageID ...
    0x01, // messageID MessageID ...
    0x03 });
    stream.flip();
    // Allocate a BindRequest Container
    LdapMessageContainer<SearchResultEntry> ldapMessageContainer = new LdapMessageContainer<>(codec);
    Asn1Decoder.decode(stream, ldapMessageContainer);
