@Test
public void testAdDirSyncControl() throws DecoderException, EncoderException {
    ByteBuffer bb = ByteBuffer.allocate(0x0F);
    bb.put(new byte[] { 0x30, 0x0D, // flag (LDAP_DIRSYNC_OBJECT_SECURITY, LDAP_DIRSYNC_ANCESTORS_FIRST_ORDER)
    0x02, // flag (LDAP_DIRSYNC_OBJECT_SECURITY, LDAP_DIRSYNC_ANCESTORS_FIRST_ORDER)
    0x02, // flag (LDAP_DIRSYNC_OBJECT_SECURITY, LDAP_DIRSYNC_ANCESTORS_FIRST_ORDER)
    0x08, // flag (LDAP_DIRSYNC_OBJECT_SECURITY, LDAP_DIRSYNC_ANCESTORS_FIRST_ORDER)
    0x01, // maxReturnLength (no limit)
    0x02, // maxReturnLength (no limit)
    0x01, // maxReturnLength (no limit)
    0x00, 0x04, 0x04, // the cookie
    'x', // the cookie
    'k', // the cookie
    'c', // the cookie
    'd' });
    bb.flip();
    AdDirSyncResponseFactory factory = (AdDirSyncResponseFactory) codec.getResponseControlFactories().get(AdDirSyncResponse.OID);
    AdDirSyncResponse adDirSyncResponse = factory.newControl();
    factory.decodeValue(adDirSyncResponse, bb.array());
    assertEquals(EnumSet.of(AdDirSyncResponseFlag.LDAP_DIRSYNC_OBJECT_SECURITY, AdDirSyncResponseFlag.LDAP_DIRSYNC_ANCESTORS_FIRST_ORDER), adDirSyncResponse.getFlags());
    assertEquals(0, adDirSyncResponse.getMaxReturnLength());
    assertEquals("xkcd", Strings.utf8ToString(adDirSyncResponse.getCookie()));
    // Check the reverse encoding
    Asn1Buffer asn1Buffer = new Asn1Buffer();
    factory.encodeValue(asn1Buffer, adDirSyncResponse);
    assertArrayEquals(bb.array(), asn1Buffer.getBytes().array());
}

