@Test
public void testDecodeOffsetWithContextID() throws DecoderException, EncoderException {
    ByteBuffer bb = ByteBuffer.allocate(0x16);
    bb.put(new byte[] { // VirtualListViewRequest ::= SEQUENCE {
    0x30, // VirtualListViewRequest ::= SEQUENCE {
    0x14, //    beforeCount    INTEGER (0..maxInt),
    0x02, //    beforeCount    INTEGER (0..maxInt),
    0x01, //    beforeCount    INTEGER (0..maxInt),
    0x01, //    afterCount     INTEGER (0..maxInt),
    0x02, //    afterCount     INTEGER (0..maxInt),
    0x01, //    afterCount     INTEGER (0..maxInt),
    0x01, //    target       CHOICE {
    (byte) 0xA0, //    target       CHOICE {
    0x06, //                   byOffset        [0] SEQUENCE {
    //                        offset          INTEGER (1 .. maxInt),
    0x02, //                        offset          INTEGER (1 .. maxInt),
    0x01, //                        offset          INTEGER (1 .. maxInt),
    0x01, //                        contentCount    INTEGER (0 .. maxInt) },
    0x02, //                        contentCount    INTEGER (0 .. maxInt) },
    0x01, //                        contentCount    INTEGER (0 .. maxInt) },
    0x01, //    contextID     OCTET STRING OPTIONAL }
    0x04, //    contextID     OCTET STRING OPTIONAL }
    0x04, 'a', 'b', 'c', 'd' });
    bb.flip();
    // Test decoding
    VirtualListViewRequestFactory factory = (VirtualListViewRequestFactory) codec.getRequestControlFactories().get(VirtualListViewRequest.OID);
    VirtualListViewRequest virtualListView = factory.newControl();
    factory.decodeValue(virtualListView, bb.array());
    assertEquals(1, virtualListView.getBeforeCount());
    assertEquals(1, virtualListView.getAfterCount());
    assertTrue(virtualListView.hasOffset());
    assertEquals(1, virtualListView.getOffset());
    assertEquals(1, virtualListView.getContentCount());
    assertEquals("abcd", Strings.utf8ToString(virtualListView.getContextId()));
    // Check the reverse encoding
    Asn1Buffer asn1Buffer = new Asn1Buffer();
    factory.encodeValue(asn1Buffer, virtualListView);
    assertArrayEquals(bb.array(), asn1Buffer.getBytes().array());
}

