@Test
public void testLdifParserRFC2849Sample6() throws Exception, Exception {
    String ldif = "version: 1\n" + // First entry modification : ADD
    "# Add a new entry\n" + "dn: cn=Fiona Jensen, ou=Marketing, dc=airius, dc=com\n" + "changetype: add\n" + "objectclass: top\n" + "objectclass: person\n" + "objectclass: organizationalPerson\n" + "cn: Fiona Jensen\n" + "sn: Jensen\n" + "uid: fiona\n" + "telephonenumber: +1 408 555 1212\n" + "jpegphoto:< file:" + FIONA_JPEG_FILE.getAbsolutePath() + "\n" + "\n" + // Second entry modification : DELETE
    "# Delete an existing entry\n" + "dn: cn=Robert Jensen, ou=Marketing, dc=airius, dc=com\n" + "changetype: delete\n" + "\n" + // Third entry modification : MODRDN
    "# Modify an entry's relative distinguished name\n" + "dn: cn=Paul Jensen, ou=Product Development, dc=airius, dc=com\n" + "changetype: modrdn\n" + "newrdn: cn=Paula Jensen\n" + "deleteoldrdn: 1\n" + "\n" + // Forth entry modification : MODRDN
    "# Rename an entry and move all of its children to a new location in\n" + "# the directory tree (only implemented by LDAPv3 servers).\n" + "dn: ou=PD Accountants, ou=Product Development, dc=airius, dc=com\n" + "changetype: moddn\n" + "newrdn: ou=Product Development Accountants\n" + "deleteoldrdn: 0\n" + "newsuperior: ou=Accounting, dc=airius, dc=com\n" + "# Modify an entry: add an additional value to the postaladdress\n" + "# attribute, completely delete the description attribute, replace\n" + "# the telephonenumber attribute with two values, and delete a specific\n" + "# value from the facsimiletelephonenumber attribute\n" + "\n" + // Fitfh entry modification : MODIFY
    "dn: cn=Paula Jensen, ou=Product Development, dc=airius, dc=com\n" + "changetype: modify\n" + "add: postaladdress\n" + "postaladdress: 123 Anystreet $ Sunnyvale, CA $ 94086\n" + "-\n" + "delete: description\n" + "-\n" + "replace: telephonenumber\n" + "telephonenumber: +1 408 555 1234\n" + "telephonenumber: +1 408 555 5678\n" + "-\n" + "delete: facsimiletelephonenumber\n" + "facsimiletelephonenumber: +1 408 555 9876\n" + "-\n" + "\n" + // Sixth entry modification : MODIFY
    "# Modify an entry: replace the postaladdress attribute with an empty\n" + "# set of values (which will cause the attribute to be removed), and\n" + "# delete the entire description attribute. Note that the first will\n" + "# always succeed, while the second will only succeed if at least\n" + "# one value for the description attribute is present.\n" + "dn: cn=Ingrid Jensen, ou=Product Support, dc=airius, dc=com\n" + "changetype: modify\n" + "replace: postaladdress\n" + "-\n" + "delete: description\n" + "-\n";
    LdifReader reader = new LdifReader();
    List<LdifEntry> entries = reader.parseLdif(ldif);
    reader.close();
    String[][][] values = { // First entry modification : ADD
    { { "dn", "cn=Fiona Jensen, ou=Marketing, dc=airius, dc=com" }, { "objectclass", "top" }, { "objectclass", "person" }, { "objectclass", "organizationalPerson" }, { "cn", "Fiona Jensen" }, { "sn", "Jensen" }, { "uid", "fiona" }, { "telephonenumber", "+1 408 555 1212" }, { "jpegphoto", "" } }, // Second entry modification : DELETE
    { { "dn", "cn=Robert Jensen, ou=Marketing, dc=airius, dc=com" } }, // Third entry modification : MODRDN
    { { "dn", "cn=Paul Jensen, ou=Product Development, dc=airius, dc=com" }, { "cn=Paula Jensen" } }, // Forth entry modification : MODRDN
    { { "dn", "ou=PD Accountants, ou=Product Development, dc=airius, dc=com" }, { "ou=Product Development Accountants" }, { "ou=Accounting, dc=airius, dc=com" } }, // Fitfh entry modification : MODIFY
    { { "dn", "cn=Paula Jensen, ou=Product Development, dc=airius, dc=com" }, // add
    { "postaladdress", "123 Anystreet $ Sunnyvale, CA $ 94086" }, // delete
    { "description" }, // replace
    { "telephonenumber", "+1 408 555 1234", "+1 408 555 5678" }, // delete
    { "facsimiletelephonenumber", "+1 408 555 9876" } }, // Sixth entry modification : MODIFY
    { { "dn", "cn=Ingrid Jensen, ou=Product Support, dc=airius, dc=com" }, // replace
    { "postaladdress" }, // delete
    { "description" } } };
    LdifEntry entry = entries.get(0);
    assertTrue(entry.isChangeAdd());
    for (int i = 0; i < values.length; i++) {
        if ("dn".equalsIgnoreCase(values[0][i][0])) {
            assertEquals(values[0][i][1], entry.getDn().getName());
        } else if ("jpegphoto".equalsIgnoreCase(values[0][i][0])) {
            Attribute attr = entry.get(values[0][i][0]);
            assertEquals(Strings.dumpBytes(data), Strings.dumpBytes(attr.getBytes()));
        } else {
            Attribute attr = entry.get(values[0][i][0]);
            if (attr.contains(values[0][i][1])) {
                assertTrue(true);
            } else {
                assertTrue(attr.contains(values[0][i][1].getBytes(StandardCharsets.UTF_8)));
            }
        }
    }
    // Second entry
    entry = entries.get(1);
    assertTrue(entry.isChangeDelete());
    assertEquals(values[1][0][1], entry.getDn().getName());
    // Third entry
    entry = entries.get(2);
    assertTrue(entry.isChangeModRdn());
    assertEquals(values[2][0][1], entry.getDn().getName());
    assertEquals(values[2][1][0], entry.getNewRdn());
    assertTrue(entry.isDeleteOldRdn());
    // Forth entry
    entry = entries.get(3);
    assertTrue(entry.isChangeModDn());
    assertEquals(values[3][0][1], entry.getDn().getName());
    assertEquals(values[3][1][0], entry.getNewRdn());
    assertFalse(entry.isDeleteOldRdn());
    assertEquals(values[3][2][0], entry.getNewSuperior());
    // Fifth entry
    entry = entries.get(4);
    List<Modification> modifs = entry.getModifications();
    assertTrue(entry.isChangeModify());
    assertEquals(values[4][0][1], entry.getDn().getName());
    // "add: postaladdress"
    // "postaladdress: 123 Anystreet $ Sunnyvale, CA $ 94086"
    Modification item = modifs.get(0);
    assertEquals(ModificationOperation.ADD_ATTRIBUTE, item.getOperation());
    assertEquals(values[4][1][0], item.getAttribute().getId());
    assertTrue(item.getAttribute().contains(values[4][1][1]));
    // "delete: description\n" +
    item = modifs.get(1);
    assertEquals(ModificationOperation.REMOVE_ATTRIBUTE, item.getOperation());
    assertEquals(values[4][2][0], item.getAttribute().getId());
    // "replace: telephonenumber"
    // "telephonenumber: +1 408 555 1234"
    // "telephonenumber: +1 408 555 5678"
    item = modifs.get(2);
    assertEquals(ModificationOperation.REPLACE_ATTRIBUTE, item.getOperation());
    assertEquals(values[4][3][0], item.getAttribute().getId());
    assertTrue(item.getAttribute().contains(values[4][3][1], values[4][3][2]));
    // "delete: facsimiletelephonenumber"
    // "facsimiletelephonenumber: +1 408 555 9876"
    item = modifs.get(3);
    assertEquals(ModificationOperation.REMOVE_ATTRIBUTE, item.getOperation());
    assertEquals(values[4][4][0], item.getAttribute().getId());
    assertTrue(item.getAttribute().contains(values[4][4][1]));
    // Sixth entry
    entry = entries.get(5);
    modifs = entry.getModifications();
    assertTrue(entry.isChangeModify());
    assertEquals(values[5][0][1], entry.getDn().getName());
    // "replace: postaladdress"
    item = modifs.get(0);
    assertEquals(ModificationOperation.REPLACE_ATTRIBUTE, item.getOperation());
    assertEquals(values[5][1][0], item.getAttribute().getId());
    // "delete: description"
    item = modifs.get(1);
    assertEquals(ModificationOperation.REMOVE_ATTRIBUTE, item.getOperation());
    assertEquals(values[5][2][0], item.getAttribute().getId());
}

