 *
 * @throws LdapException
 */
@Test
public void testEquals() throws LdapException {
    Rdn rdn = new Rdn("a=b + c=d + e=f");
    assertFalse(rdn.equals(null));
    assertFalse(rdn.equals("test"));
    assertFalse(rdn.equals(new Rdn("a=c + c=d + e=f")));
