    char[] chars = new char[58];
    int pos = 0;
    for (char c = 0x0000; c < 0x0008; c++) {
        chars[pos++] = c;
    }
    for (char c = 0x000E; c < 0x001F; c++) {
        chars[pos++] = c;
    }
    for (char c = 0x007F; c < 0x0084; c++) {
        chars[pos++] = c;
    }
    for (char c = 0x0086; c < 0x009F; c++) {
        chars[pos++] = c;
    }
    chars[pos++] = 0x00AD;
    assertEquals("  ", normalizer.normalize(new String(chars)));
}

