@Test
public void testRenderQdescrs() {
    assertEquals("", SchemaUtils.renderQDescrs(new StringBuilder(), (List<String>) null).toString());
    assertEquals("", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] {})).toString());
    assertEquals("'name1'", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] { "name1" })).toString());
    assertEquals("( 'name1' 'name2' )", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] { "name1", "name2" })).toString());
    assertEquals("( 'name1' 'name2' 'name3' )", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] { "name1", "name2", "name3" })).toString());
    assertEquals("", SchemaUtils.renderQDescrs(new StringBuilder(), (List<String>) null).toString());
    assertEquals("", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] {})).toString());
    assertEquals("'name1'", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] { "name1" })).toString());
    assertEquals("( 'name1' 'name2' )", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] { "name1", "name2" })).toString());
    assertEquals("( 'name1' 'name2' 'name3' )", SchemaUtils.renderQDescrs(new StringBuilder(), Arrays.asList(new String[] { "name1", "name2", "name3" })).toString());
