/**
 * Check that non printable Strings are not accepted. We created Strings
 * which contains only one char which is not in the acceptable set of
 * printable chars.
 */
@Test
public void testWrongStrings() {
    for (int i = 0; i < 0x1F; i++) {
        assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) i })));
    }
    for (int i = 0x21; i < 0x26; i++) {
        assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) i })));
    }
    for (int i = 0x5B; i < 0x60; i++) {
        assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) i })));
    }
    for (int i = 0x7B; i < 0x7F; i++) {
        assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) i })));
    }
    assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) 0x2A })));
    assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) 0x3B })));
    assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) 0x3C })));
    assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) 0x3E })));
    assertFalse(checker.isValidSyntax(Strings.utf8ToString(new byte[] { (byte) 0x40 })));
}

