public void fractionCloseToOne() throws ParseException {
    GeneralizedTime close = new GeneralizedTime("20000101000000.9994Z");
    assertThat(close.getDate(), is(equalTo(format.parse("01/01/2000 00:00:00.999 GMT"))));
