@Test
public void testMapToString() {
    class Value {

        String name;

        int val;

        public Value(String name, int val) {
            this.name = name;
            this.val = val;
        }

        public String toString() {
            return "[" + name + ", " + val + "]";
        }
    }
    Map<String, Value> map = new HashMap<String, Value>();
    map.put("elem1", new Value("name1", 1));
    map.put("elem2", new Value("name2", 2));
    map.put("elem3", new Value("name3", 3));
    String result = Strings.mapToString(map);
    boolean res = "elem1 = '[name1, 1]', elem2 = '[name2, 2]', elem3 = '[name3, 3]'".equals(result) || "elem1 = '[name1, 1]', elem3 = '[name3, 3]', elem2 = '[name2, 2]'".equals(result) || "elem2 = '[name2, 2]', elem1 = '[name1, 1]', elem3 = '[name3, 3]'".equals(result) || "elem2 = '[name2, 2]', elem3 = '[name3, 3]', elem1 = '[name1, 1]'".equals(result) || "elem3 = '[name3, 3]', elem1 = '[name1, 1]', elem2 = '[name2, 2]'".equals(result) || "elem3 = '[name3, 3]', elem2 = '[name2, 2]', elem1 = '[name1, 1]'".equals(result);
    assertTrue(res);
}

